//! Who owns a file Orq may see in a project: Orq never deletes, moves or
//! rewrites what the project or the TDD/MCP tooling owns.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ownership {
    /// Defined by the project (`.tdd-features.json`).
    Project,
    /// Generated by the TDD or project MCP servers.
    Mcp,
    /// Not a known tool file.
    Unowned,
}

const MCP_FILES: [&str; 3] = [".mcp.json", ".project-mcp", ".mcpctl"];
const MCP_PREFIXES: [&str; 2] = [".tdd-", ".mcpctl"];

/// Classifies a file by its name alone.
pub fn classify(name: &str) -> Ownership {
    if name == ".tdd-features.json" {
        return Ownership::Project;
    }
    if MCP_FILES.contains(&name) || MCP_PREFIXES.iter().any(|prefix| name.starts_with(prefix)) {
        return Ownership::Mcp;
    }
    Ownership::Unowned
}

/// Whether a generic Orq cleanup may delete the file. Project and MCP files never.
pub fn may_orq_delete(name: &str) -> bool {
    classify(name) == Ownership::Unowned
}
